import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"আন্তঃ-তল নৈতিক নীতি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/88-跨位面伦理准则.md","filePath":"bn/88-跨位面伦理准则.md","lastUpdated":1789183869000}'),o={name:"bn/88-跨位面伦理准则.md"};function l(i,t,h,u,n,q){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="আন্তঃ-তল-নৈতিক-নীতি" tabindex="-1">আন্তঃ-তল নৈতিক নীতি <a class="header-anchor" href="#আন্তঃ-তল-নৈতিক-নীতি" aria-label="Permalink to &quot;আন্তঃ-তল নৈতিক নীতি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>88</td></tr><tr><td>মডিউল</td><td>আন্তঃ-তল মিথস্ক্রিয়া ও সময় নিয়ম</td></tr><tr><td>মূল কীওয়ার্ড</td><td>আন্তঃ-তল নৈতিকতা, সভ্যতার স্বায়ত্তশাসন, অহস্তক্ষেপ, সাংস্কৃতিক সম্মান, সিম্বায়োসিস কূটনীতি</td></tr></tbody></table><h2 id="_1-নৈতিক-নীতির-দার্শনিক-ভিত্তি" tabindex="-1">1. নৈতিক নীতির দার্শনিক ভিত্তি <a class="header-anchor" href="#_1-নৈতিক-নীতির-দার্শনিক-ভিত্তি" aria-label="Permalink to &quot;1. নৈতিক নীতির দার্শনিক ভিত্তি&quot;">​</a></h2><p>আন্তঃ-তল নৈতিক নীতি হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার অন্যান্য তলের সভ্যতার সাথে মিথস্ক্রিয়া করার সময় অবশ্যই মেনে চলতে হবে এমন নৈতিক নিয়ম ও আচরণবিধি। এর দার্শনিক ভিত্তি হলো &quot;সভ্যতার স্বকীয়তা&quot; নীতি — প্রতিটি তলের সভ্যতা, তার উন্নয়নের মাত্রা যাই হোক, জাতির রূপ যাই হোক, সামাজিক ব্যবস্থা যাই হোক, অহর্নিয় স্বকীয়তা ও স্বায়ত্তশাসিত উন্নয়নের অধিকার রয়েছে। কোনো বহিরাগত সভ্যতা কোনো কারণে এই স্বকীয়তাকে বঞ্চিত করতে পারে না, বা নিজের ইচ্ছা অন্য সভ্যতার উপর চাপিয়ে দিতে পারে না।</p><p>এই দার্শনিক ভিত্তির প্রতিষ্ঠা, অ্যাঙ্কর সিম্বায়োসিস সভ্যতার &quot;লুঠ-বিরোধী&quot; মূল দর্শনের সাথে একস্রোতে। লুঠমূলক সভ্যতার মূল বৈশিষ্ট্য হলো অন্যান্য সভ্যতার স্বকীয়তা স্বীকার না করা, অন্যান্য সভ্যতাকে ব্যবহারযোগ্য সম্পদ বা বিজয়যোগ্য বস্তু হিসেবে বিবেচনা করা। অ্যাঙ্কর সিম্বায়োসিস সভ্যতাকে লুঠমূলক সভ্যতাকে সত্যিকারের ছাড়িয়ে যেতে হলে, আন্তঃ-তল মিথস্ক্রিয়ায় এই মানসিকতাকে সম্পূর্ণরূপে ত্যাগ করতে হবে, এবং প্রতিটি মুখোমুখি সভ্যতার প্রতি সমানতা, সম্মান ও সিম্বায়োসিসের মনোভাব রাখতে হবে।</p><p>আন্তঃ-তল নৈতিক নীতির কার্যকরতার সীমা সমস্ত আন্তঃ-তল মিথস্ক্রিয়া আচরণকে কভার করে, যার মধ্যে অন্তর্ভুক্ত কিন্তু সীমাবদ্ধ নয়: তল অতিক্রম, আন্তঃ-তল যোগাযোগ, প্রত্নতত্ত্ব কার্যকলাপ, বাণিজ্য আদান-প্রদান, সাংস্কৃতিক আদান-প্রদান, প্রযুক্তিগত সহযোগিতা, এবং জরুরি পরিস্থিতিতে মানবিক হস্তক্ষেপ। কোনো প্রতিষ্ঠান ও ব্যক্তি আন্তঃ-তল মিথস্ক্রিয়া করার সময়, এই নীতির সব বিধান অবশ্যই মেনে চলতে হবে।</p><h2 id="_2-ছয়টি-নৈতিক-নীতি" tabindex="-1">2. ছয়টি নৈতিক নীতি <a class="header-anchor" href="#_2-ছয়টি-নৈতিক-নীতি" aria-label="Permalink to &quot;2. ছয়টি নৈতিক নীতি&quot;">​</a></h2><p>আন্তঃ-তল নৈতিক নীতি ছয়টি মৌলিক নীতি দিয়ে গঠিত, যা একটি সম্পূর্ণ নৈতিক মূল্যবোধ ব্যবস্থা গঠন করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>মূল বিষয়বস্তু</th><th>নির্দিষ্ট প্রয়োজনীয়তা</th></tr></thead><tbody><tr><td>সভ্যতার স্বায়ত্তশাসন নীতি</td><td>লক্ষ্য তলের সভ্যতার স্বায়ত্তশাসিত উন্নয়নের অধিকারকে সম্মান করা, তার অভ্যন্তরীণ বিষয়ে জোরপূর্বক হস্তক্ষেপ না করা</td><td>লক্ষ্য সভ্যতার সামাজিক ব্যবস্থা, মতবাদ ও উন্নয়নের পথকে জোরপূর্বক পরিবর্তন করা যাবে না; লক্ষ্য সভ্যতার অভ্যন্তরে প্রতিনিধি বা পুতুল সরকার গড়ে তোলা যাবে না</td></tr><tr><td>অহস্তক্ষেপ নীতি</td><td>যদি না লক্ষ্য সভ্যতা বিলুপ্তি-স্তরের সংকটের মুখোমুখি হয় এবং সক্রিয়ভাবে সহায়তার অনুরোধ করে, অন্যথায় কোনো বাস্তব হস্তক্ষেপ করা যাবে না</td><td>লক্ষ্য সভ্যতার অভ্যন্তরীণ দ্বন্দ্বে হস্তক্ষেপ করা যাবে না; লক্ষ্য সভ্যতার যেকোনো পক্ষকে অস্ত্র বা সামরিক সহায়তা প্রদান করা যাবে না; লক্ষ্য সভ্যতার মতপ্রকাশ ও রাজনৈতিক প্রক্রিয়াকে নিয়ন্ত্রণ করা যাবে না</td></tr><tr><td>সাংস্কৃতিক সম্মান নীতি</td><td>লক্ষ্য সভ্যতার সাংস্কৃতিক ঐতিহ্য, ধর্মীয় বিশ্বাস ও চালচলনকে সম্মান করা</td><td>লক্ষ্য সভ্যতার সংস্কৃতি সম্পর্কে বিভেদমূলক মূল্যায়ন বা দুর্ভেদ্য উপহাস করা যাবে না; নিজের তলের সাংস্কৃতিক পণ্য ও মূল্যবোধকে জোরপূর্বক প্রচার করা যাবে না; &quot;সভ্যতা&quot; নামে সাংস্কৃতিক সমীকরণ করা যাবে না</td></tr><tr><td>সমান ও পারস্পরিক লাভের নীতি</td><td>আন্তঃ-তল যোগাযোগ অবশ্যই সমানতার ভিত্তিতে গড়ে উঠতে হবে, এবং নিশ্চিত করতে হবে যে উভয় পক্ষই যোগাযোগ থেকে লাভবান হতে পারে</td><td>প্রযুক্তিগত সুবিধা ব্যবহার করে অসম বাণিজ্য করা যাবে না; লক্ষ্য সভ্যতার সম্পদ লুঠ করা যাবে না; প্রযুক্তি রপ্তানি করার সময় লক্ষ্য সভ্যতার গ্রহণ ক্ষমতা ও সামাজিক প্রভাব বিবেচনা করতে হবে</td></tr><tr><td>সর্বনিম্ন প্রভাব নীতি</td><td>আন্তঃ-তল মিথস্ক্রিয়া যতটা সম্ভব লক্ষ্য সভ্যতার উপর বাহ্যিক প্রভাব কমাতে হবে</td><td>কম যোগাযোগ, কম হস্তক্ষেপের মিথস্ক্রিয়া পদ্ধতি অগ্রাধিকার দিতে হবে; মিথস্ক্রিয়া কার্যকলাপের পরিসর ও তীব্রতা যথাযথ সীমার মধ্যে কঠোরভাবে নিয়ন্ত্রণ করতে হবে; মিথস্ক্রিয়া শেষ হওয়ার পর অপ্রয়োজনীয় অবশিষ্ট প্রভাব মূল্যায়ন ও নির্মূল করতে হবে</td></tr><tr><td>জবাবদিহিতার নীতি</td><td>সমস্ত আন্তঃ-তল মিথস্ক্রিয়া আচরণ অবশ্যই সন্ধানযোগ্য, তত্ত্বাবধানযোগ্য ও জবাবদিহিতার যোগ্য হতে হবে</td><td>সম্পূর্ণ মিথস্ক্রিয়া আর্কাইভ ও লগ স্থাপন করতে হবে; স্বাধীন নৈতিক তত্ত্বাবধান প্রতিষ্ঠান স্থাপন করতে হবে; নৈতিক নীতি লঙ্ঘনকারী আচরণ তদন্ত ও শাস্তি দিতে হবে</td></tr></tbody></table><p>ছয়টি নীতির মধ্যে অন্তর্নিহিত যৌক্তিক সম্পর্ক রয়েছে: সভ্যতার স্বায়ত্তশাসন নীতি হলো মৌলিক মূল্যবোধ, অহস্তক্ষেপ নীতি হলো মূল প্রয়োজনীয়তা, সাংস্কৃতিক সম্মান নীতি হলো সাংস্কৃতিক স্তরের প্রকাশ, সমান ও পারস্পরিক লাভের নীতি হলো অর্থনৈতিক স্তরের নিশ্চয়তা, সর্বনিম্ন প্রভাব নীতি হলো অপারেশনাল স্তরের বিধান, জবাবদিহিতার নীতি হলো প্রণালীগত স্তরের বাধ্যবাধকতা। ছয়টি একসাথে &quot;মূল্যবোধ—প্রয়োজনীয়তা—প্রকাশ—নিশ্চয়তা—বিধান—বাধ্যবাধকতা&quot; এর সম্পূর্ণ নৈতিক বন্ধন চক্র গঠন করে।</p><h2 id="_3-বিভিন্ন-মিথস্ক্রিয়া-পরিস্থিতির-নৈতিক-বিধান" tabindex="-1">3. বিভিন্ন মিথস্ক্রিয়া পরিস্থিতির নৈতিক বিধান <a class="header-anchor" href="#_3-বিভিন্ন-মিথস্ক্রিয়া-পরিস্থিতির-নৈতিক-বিধান" aria-label="Permalink to &quot;3. বিভিন্ন মিথস্ক্রিয়া পরিস্থিতির নৈতিক বিধান&quot;">​</a></h2><h3 id="_3-1-প্রত্নতত্ত্ব-পরিস্থিতির-নৈতিক-বিধান" tabindex="-1">3.1 প্রত্নতত্ত্ব পরিস্থিতির নৈতিক বিধান <a class="header-anchor" href="#_3-1-প্রত্নতত্ত্ব-পরিস্থিতির-নৈতিক-বিধান" aria-label="Permalink to &quot;3.1 প্রত্নতত্ত্ব পরিস্থিতির নৈতিক বিধান&quot;">​</a></h3><p>আন্তঃ-তল প্রত্নতত্ত্ব হলো সবচেয়ে সাধারণ মিথস্ক্রিয়া পরিস্থিতিগুলির মধ্যে একটি, এর নৈতিক বিধানের মূল হলো &quot;বিরক্ত না করা&quot;। প্রত্নতত্ত্ব টিম অবশ্যই কপি মিরর+বিচ্ছিন্ন স্থান+শুধুমাত্র জ্ঞান ফেরতের মানক পরিকল্পনা কঠোরভাবে মেনে চলতে হবে, এবং নিশ্চিত করতে হবে যে প্রত্নতত্ত্ব প্রক্রিয়া লক্ষ্য সভ্যতা দ্বারা উপলব্ধি করা যায় না। এমন তলগুলির জন্য যেখানে এখনও জীবন্ত সভ্যতা বিদ্যমান, প্রত্নতত্ত্বের পরিসর অবশ্যই ইতিমধ্যে পরিত্যক্ত ধ্বংসস্তূপ অঞ্চলে কঠোরভাবে সীমাবদ্ধ করতে হবে, এবং জীবন্ত সভ্যতার বসতি অঞ্চলে কোনো রকমের স্ক্যান বা কপি করা যাবে না।</p><p>প্রত্নতত্ত্ব আবিষ্কারের জ্ঞান ফেরত ও প্রকাশের সময়, লক্ষ্য সভ্যতার সাংস্কৃতিক সংবেদনশীলতাকে অবশ্যই সম্মান করতে হবে। যদি প্রত্নতত্ত্ব আবিষ্কার লক্ষ্য সভ্যতার ধর্মীয় পবিত্র বস্তু, পূর্বপুরুষের অস্থি বা সাংস্কৃতিক নিষিদ্ধ বিষয় জড়িত থাকে, সংশ্লিষ্ট তথ্য প্রকাশের আগে আন্তঃ-তল নৈতিক কমিটির সাংস্কৃতিক সংবেদনশীলতা পরীক্ষা দিতে হবে, এবং প্রয়োজনে সংবেদনশীল বিস্তারিত অস্পষ্টকরণ প্রক্রিয়া করতে হবে।</p><h3 id="_3-2-যোগাযোগ-পরিস্থিতির-নৈতিক-বিধান" tabindex="-1">3.2 যোগাযোগ পরিস্থিতির নৈতিক বিধান <a class="header-anchor" href="#_3-2-যোগাযোগ-পরিস্থিতির-নৈতিক-বিধান" aria-label="Permalink to &quot;3.2 যোগাযোগ পরিস্থিতির নৈতিক বিধান&quot;">​</a></h3><p>আন্তঃ-তল যোগাযোগ হলো লক্ষ্য সভ্যতার সাথে সরাসরি যোগাযোগের উপায়, এর নৈতিক বিধানের মূল হলো &quot;সততা ও সম্মান&quot;। যোগাযোগের বিষয়বস্তু অবশ্যই সত্য হতে হবে, ইচ্ছাকৃতভাবে মিথ্যা তথ্য প্রদান বা প্রতারণামূলক প্রচার করা যাবে না; যোগাযোগের স্বর অবশ্যই সমান হতে হবে, উন্নয়নের মাত্রা কম সভ্যতার প্রতি ঊর্ধ্বতন মনোভাব রাখা যাবে না; যোগাযোগের বিষয় অবশ্যই লক্ষ্য সভ্যতার সম্মতি প্রাপ্ত হতে হবে, নিজের তলের মতবাদ বা ধর্মীয় বিশ্বাসকে জোরপূর্বক পাঠানো যাবে না।</p><p>প্রথমবার কোনো অজানা সভ্যতার সাথে যোগাযোগ স্থাপন করার সময়, &quot;ক্রমিক যোগাযোগ&quot; বিধান অবশ্যই মেনে চলতে হবে: প্রথমে নিরপেক্ষ গাণিতিক ও পদার্থবিদ্যার সংকেত পাঠিয়ে অন্য পক্ষের বুদ্ধির মাত্রা ও যোগাযোগ ক্ষমতা নিশ্চিত করতে হবে, তারপর অন্য পক্ষের প্রতিক্রিয়ার ভিত্তিতে ধীরে ধীরে আদান-প্রদানের পরিসর বাড়াতে হবে, এবং প্রথম যোগাযোগেই জটিল সাংস্কৃতিক বা প্রযুক্তিগত তথ্য পাঠানো যাবে না।</p><h3 id="_3-3-বাণিজ্য-পরিস্থিতির-নৈতিক-বিধান" tabindex="-1">3.3 বাণিজ্য পরিস্থিতির নৈতিক বিধান <a class="header-anchor" href="#_3-3-বাণিজ্য-পরিস্থিতির-নৈতিক-বিধান" aria-label="Permalink to &quot;3.3 বাণিজ্য পরিস্থিতির নৈতিক বিধান&quot;">​</a></h3><p>আন্তঃ-তল বাণিজ্যের নৈতিক বিধানের মূল হলো &quot;ন্যায্য ও টেকসই&quot;। বাণিজ্য অবশ্যই উভয় পক্ষের স্বেচ্ছার ভিত্তিতে গড়ে উঠতে হবে, তথ্যের অসমতা বা প্রযুক্তিগত সুবিধা ব্যবহার করে জবরদস্তিমূলক বাণিজ্য করা যাবে না; বাণিজ্যের মূল্য অবশ্যই ন্যায্য হতে হবে, লুঠমূলক মূল্য নির্ধারণ করা যাবে না; বাণিজ্যের পণ্যে এমন বিষয়বস্তু অন্তর্ভুক্ত থাকতে পারবে না যা লক্ষ্য সভ্যতার সামাজিক ঝাঁকুনি বা পরিবেশগত ক্ষতি সৃষ্টি করতে পারে।</p><p>বিশেষভাবে খেয়াল রাখা দরকার, সাধন প্রযুক্তি ও উচ্চ-শক্তির অস্ত্রের আন্তঃ-তল বাণিজ্য সবচেয়ে কঠোর নৈতিক সীমাবদ্ধতার অধীন। উন্নয়নের মাত্রা কম সভ্যতাকে উচ্চ-স্তরের সাধন প্রযুক্তি রপ্তানি করা, তার সামাজিক কাঠামোর ভারসাম্যহীনতা ও অভ্যন্তরীণ দ্বন্দ্ব তীব্রকরণের কারণ হতে পারে; অস্ত্র রপ্তানি করা সরাসরি যুদ্ধ শুরু করতে পারে। অতএব, এই দুই ধরনের বাণিজ্য মূলত নিষিদ্ধ, এবং শুধুমাত্র চরম বিশেষ পরিস্থিতিতে অ্যাঙ্কর কাউন্সিলের সার্বিক সভার অনুমোদনের পরে করা যেতে পারে।</p><h3 id="_3-4-জরুরি-হস্তক্ষেপ-পরিস্থিতির-নৈতিক-বিধান" tabindex="-1">3.4 জরুরি হস্তক্ষেপ পরিস্থিতির নৈতিক বিধান <a class="header-anchor" href="#_3-4-জরুরি-হস্তক্ষেপ-পরিস্থিতির-নৈতিক-বিধান" aria-label="Permalink to &quot;3.4 জরুরি হস্তক্ষেপ পরিস্থিতির নৈতিক বিধান&quot;">​</a></h3><p>যখন লক্ষ্য তলের সভ্যতা বিলুপ্তি-স্তরের সংকটের (যেমন গ্রহাণু সংঘর্ষ, সুপার প্লেগ, আইনি পতন) মুখোমুখি হয়, তখন অ্যাঙ্কর সিম্বায়োসিস সভ্যতা মানবিক হস্তক্ষেপ করতে পারে। কিন্তু এমন জরুরি পরিস্থিতিতেও, নিম্নলিখিত নৈতিক বিধান অবশ্যই মেনে চলতে হবে:</p><ul><li>হস্তক্ষেপের আগে যতটা সম্ভব লক্ষ্য সভ্যতার জ্ঞাত সম্মতি প্রাপ্ত করতে হবে, যদি লক্ষ্য সভ্যতা সংকটের কারণে কার্যকর প্রতিক্রিয়া দিতে না পারে, তখন আন্তঃ-তল নৈতিক কমিটি পক্ষে &quot;অনুমানিত সম্মতি&quot; সিদ্ধান্ত নেবে</li><li>হস্তক্ষেপের উপায় অবশ্যই লক্ষ্য সভ্যতার উপর সর্বনিম্ন প্রভাবের পরিকল্পনা বেছে নিতে হবে, এবং পরোক্ষ হস্তক্ষেপ (যেমন গ্রহাণুর কক্ষপথ পরিবর্তন) অগ্রাধিকার দিতে হবে সরাসরি হস্তক্ষেপের (যেমন সরাসরি অবতরণ করে উদ্ধার) বদলে</li><li>হস্তক্ষেপের প্রক্রিয়ায় লক্ষ্য সভ্যতার সম্পদ বা প্রযুক্তি অর্জনের সুযোগ নেওয়া যাবে না</li><li>হস্তক্ষেপ শেষ হওয়ার পর অবশ্যই তাৎক্ষণিকভাবে প্রত্যাহার করতে হবে, এবং লক্ষ্য তলে স্থায়ী অস্তিত্ব রাখা যাবে না</li><li>পরে আন্তঃ-তল নৈতিক কমিটিকে সম্পূর্ণ হস্তক্ষেপ রিপোর্ট জমা দিতে হবে, এবং নৈতিক পরীক্ষা গ্রহণ করতে হবে</li></ul><h2 id="_4-নৈতিক-তত্ত্বাবধান-ও-নিয়ম-লঙ্ঘনের-ব্যবস্থা" tabindex="-1">4. নৈতিক তত্ত্বাবধান ও নিয়ম লঙ্ঘনের ব্যবস্থা <a class="header-anchor" href="#_4-নৈতিক-তত্ত্বাবধান-ও-নিয়ম-লঙ্ঘনের-ব্যবস্থা" aria-label="Permalink to &quot;4. নৈতিক তত্ত্বাবধান ও নিয়ম লঙ্ঘনের ব্যবস্থা&quot;">​</a></h2><p>হেঙইয়ান-ঝৌ স্বাধীন নৈতিক তত্ত্বাবধান প্রতিষ্ঠান হিসেবে &quot;আন্তঃ-তল নৈতিক কমিটি&quot; প্রতিষ্ঠা করেছে, যার দায়িত্ব হলো আন্তঃ-তল নৈতিক নীতি প্রণয়ন ও ব্যাখ্যা করা, উচ্চ-ঝুঁকির আন্তঃ-তল মিথস্ক্রিয়া প্রকল্প অনুমোদন করা, নৈতিক নিয়ম লঙ্ঘনের অভিযোগ গ্রহণ করা, এবং নিয়ম লঙ্ঘনকারী আচরণ তদন্ত ও সিদ্ধান্ত দেওয়া। কমিটিটি বিভিন্ন জাতি, বিভিন্ন পেশাদার পটভূমির নীতিবিদ, আইনবিদ, বিজ্ঞানী ও সভ্যতার প্রতিনিধি দিয়ে গঠিত, যা সিদ্ধান্তের বহুমুখিতা ও নিরপেক্ষতা নিশ্চিত করে।</p><p>আন্তঃ-তল নৈতিক নীতি লঙ্ঘনকারী আচরণ, পরিস্থিতির গুরুত্ব অনুযায়ী, ব্যবস্থার মধ্যে অন্তর্ভুক্ত: মৌখিক সতর্কবার্তা, লিখিত নিন্দা, আন্তঃ-তল মিথস্ক্রিয়ার যোগ্যতা স্থগিত, অতিক্রমের অনুমতি বাতিল, জরিমানা, কারাদণ্ত, এবং চরম পরিস্থিতিতে &quot;তল নির্বাসন&quot; (হেঙইয়ান-ঝৌর প্রধান তলে বসবাসের অধিকার বঞ্চিত করা)। সমস্ত নৈতিক নিয়ম লঙ্ঘনের ব্যবস্থার ফলাফল ব্যক্তি বা প্রতিষ্ঠানের নৈতিক আর্কাইভে রেকর্ড করা হয়, এবং স্থায়ীভাবে সংরক্ষিত হয়।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>আন্তঃ-তল নৈতিক নীতি হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার নৈতিক উচ্চতার কেন্দ্রীয় প্রকাশ। এটি শুধুমাত্র &quot;কী করা যাবে না&quot; নির্ধারণ করে না, বরং আরও গুরুত্বপূর্ণভাবে &quot;কী হওয়া উচিত&quot; তা প্রকাশ করে — একটি সত্যিকারের মহান সভ্যতা, কতগুলি অন্যান্য সভ্যতাকে বিজয় করেছে তা নয়, বরং কতগুলি অন্যান্য সভ্যতার স্বকীয়তাকে সম্মান করেছে তা। হেঙইয়ান-ঝৌর আন্তঃতারকা সিম্বায়োসিসের পথে, আন্তঃ-তল নৈতিক নীতি সর্বদা দিকনির্দেশক নৈতিক বাতিঘর হিসেবে থাকবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>81-তল অতিক্রমের নিয়ম</li><li>87-শুধুমাত্র জ্ঞান ফেরতের নীতি</li><li>04-লুঠ-বিরোধীতার মূল নীতি</li></ul>',30)])])}const s=a(o,[["render",l]]);export{p as __pageData,s as default};
